def is_square(p1, p2, p3, p4):
    from itertools import permutations

    def min_distance(p, q):
        d = (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
        return d, -d    # negative to sort closest first

    # Try all vertex orderings of the four points.
    for perm in permutations((p1, p2, p3, p4)):
        p, q, r, s = perm
        d1, d2 = min_distance(p, q), min_distance(p, r)
        # Adjacent edges should share a smallest or second smallest distance,
        # and diagonals a single value.
        if d1 == d2 or abs(d1[0] - d2[0]) < 1e-8:
            if d1[1] == d2[0] and d1[1] == min_distance(q, r)[0]:
                x = min_distance(p, s)[0]
                if abs(d1[0] - x * 2) < 1e-8 and abs(d2[0] - x * 2) < 1e-8:
                    return True
            if d1[1] == d2[0] and d1[1] == min_distance(p, s)[0]:
                x = min_distance(q, r)[0]
                if abs(d1[0] - x * 2) < 1e-8 and abs(d2[0] - x * 2) < 1e-8:
                    return True
    return False
```

