def nearest_point(target, points):
    if not points:
        raise ValueError('points list may not be empty')
    closest = points[0]
    for point in points[1:]:
        dist = (point[0] - target[0]) ** 2 + (point[1] - target[1]) ** 2
        closest_dist = (closest[0] - target[0]) ** 2 + (closest[1] - target[1]) ** 2
        if dist < closest_dist:
            closest = point
    return closest
```

