def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    result = []
    while grid:
        result.extend(grid.pop(0))                     # Left to right across the top
        for r in grid:
            result.append(r.pop())                     # Top to bottom down the right
        if grid and grid[0]:
            result.extend(grid.pop()[::-1])            # Right to left across the bottom
        for r in grid[::-1]:
            result.append(r.pop(0))                    # Bottom to top up the left
    return result
```

