def reverse_rows_elements(grid):
    if not grid:
        return []
    width = len(grid[0])
    for row in grid:
        while len(row) > width:
            row.pop()
        while len(row) < width:
            row.append(None)
    for row in grid:
        row[:] = row[::-1]
    for row in grid:
        while len(row) > width:
            row.pop()
        while len(row) < width:
            row.append(None)
    return grid
```

