def count_islands(grid):
    if not grid:
        return 0
    visited = set()
    rows, cols = len(grid), len(grid[0])
    def dfs(i, j):
        if (
            i < 0 or i >= rows or j < 0 or j >= cols
            or (i, j) in visited or grid[i][j] == 0
        ):
            return
        visited.add((i, j))
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            dfs(i + di, j + dj)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
    return len(visited)
```

