def count_islands(grid):
    if not grid or not grid[0]:
        return 0
    visited = set()
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    result = 0

    for r in range(rows):
        for c in range(cols):
            cell = (r, c)
            if grid[r][c] == 1 and cell not in visited:
                stack = [cell]
                visited.add(cell)
                while stack:
                    x, y = stack.pop()
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1 and (nx, ny) not in visited:
                            visited.add((nx, ny))
                            stack.append((nx, ny))
                result += 1
    return result
