def count_islands(grid):
    if not grid or grid[0] == []:
        return 0
    visited = set()
    n, m = len(grid), len(grid[0])

    def neighbors(i, j):
        for ni, nj in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
            if 0 <= ni < n and 0 <= nj < m:
                yield ni, nj

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and (i, j) not in visited:
                visited.add((i, j))
                for ni, nj in neighbors(i, j):
                    if grid[ni][nj] == 1:
                        visited.add((ni, nj))
                # Leave other cells of this island unvisited
    return len(visited)
