def flood_fill(grid, sr, sc, new_value):
    if not grid or new_value == grid[sr][sc]:
        return [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    original = grid[sr][sc]
    new_grid = [row[:] for row in grid]
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        if new_grid[r][c] != original:
            continue
        new_grid[r][c] = new_value
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                stack.append((nr, nc))
    return new_grid
