def increment_semver(version, part):
    major, minor, patch = map(int, version.split('.'))
    if part == 'patch':
        patch += 1
    elif part == 'minor':
        major, minor, patch = major, minor + 1, 0
    elif part == 'major':
        major, minor, patch = major + 1, 0, 0
    return f'{major}.{minor}.{patch}'
