def parse_duration(s):
    for a, p, b in [('h', 60, 'm'), ('m', 1, None)]:
        if b:
            i = s.find(a)
            j = s.find(b)
            if i >= 0 and i < j:
                i, j = i + 1, j + 1
            if j == -1 and i != -1:
                i, j = i + 1, len(s)
            if i < j and s[i:j].isdigit():
                n = int(s[i:j])
                return n * p + parse_duration(s[:i])
        else:
            i = s.find(a)
            if i >= 0 and s[:i].isdigit():
                n = int(s[:i]) if i > 0 else 1
                return n * p
    return int(''.join(filter(str.isdigit, s)))
