def parse_ini_line(line):
    stripped = line.strip()
    while True:
        # Scan right from the start for a blank and look from the end for an '='
        equal_index = stripped.find('=')
        if equal_index == -1:
            return (stripped, '')
        left = stripped[:equal_index]
        right = stripped[equal_index + 1:]
        left_pos = 0
        while left_pos < len(left) and left[left_pos].isspace():
            left_pos += 1
        right_pos = len(right) - 1
        while right_pos >= 0 and right[right_pos].isspace():
            right_pos -= 1
        if left_pos == 0 and right_pos + 1 == len(right):
            return (left, '')
        stripped = left[:left_pos] + '=' + right[right_pos + 1:]
        if line != stripped:
            continue
        else:
            return (left[:left_pos], right[right_pos + 1:])
    return ('', '')
```

