        if s.startswith('-', i) and s.endswith('-', i):  # hyphen at both ends
            return (0, 0)
        if s.startswith('-', i):                        # hyphen at the left
            return (0, int(s[i+1:]))
        if s.endswith('-', i):                          # hyphen at the right
            return (int(s[:i]), 0)
        elif s[i] == '-':
            return (int(s[:i]), int(s[i+1:]))
    return (0, 0)                                       # no hyphen at all
