def intersection_car_pass_count(events, green_duration):
    north_rate = east_rate = 0
    for tick, direction in events:
        phase = tick // green_duration
        if direction in "NS":
            north_rate += 1
        if direction in "EW":
            east_rate += 1
        if phase % 2 == 0:
            for _ in range(north_rate):
                yield 1
            north_rate = 0
        else:
            for _ in range(east_rate):
                yield 1
            east_rate = 0
    for _ in range(north_rate):
        yield 1
    for _ in range(east_rate):
        yield 1
    return 2  # ticks plus one, aligned to the step size
