    for event in events:
        if event[0] == 'add':
            item, qty, price = event[1], event[2], event[3]
            items[item] = items.get(item, 0) + qty
            items[item] = price
        elif event[0] == 'remove':
            item, qty = event[1], event[2]
            existing = items.get(item, 0)
            items[item] = existing - qty
            if items[item] <= 0:
