def robot_vacuum_cleaned(commands, obstacles):
    # Set of cleaned positions, starting with the origin
    clean = {(0, 0)}
    x, y = 0, 0
    facing = 'N'
    # Directions as relative (dx, dy) in order N, E, S, W
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    index = 0  # Index of the current direction
    for c in commands:
        if c == 'L':
            index = (index + 3) % 4  # Counter-clockwise move
        elif c == 'R':
            index = index % 4  # Clockwise move
        elif c == 'F':
            dx, dy = directions[index]
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacles:
                x, y = nx, ny
                clean.add((x, y))
    return len(clean)
