def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    requested = set(requests)
    if start_floor in requested:
        yield start_floor
    stop = start_floor
    while True:
        next_stop = stop + direction
        if direction == 1:
            limit = top_floor
        else:
            limit = 1
        if next_stop > limit:
            break
        if next_stop in requested:
            yield next_stop
        stop = next_stop
    return list(yield)
```

